import argparse,json,hashlib,kb,extract_workbooks
SID='src-000173';DATE='2026-11-09';extract_workbooks.DATE=DATE
SPECS={}
def seq(n,actors,events,notes=[]):
 code='sequenceDiagram\n'+''.join('participant '+i+' as '+v[0]+'\n' for i,v in actors.items())
 for a,b,label in events:code+=a+'->>'+b+': '+label+'\n'
 if n==25:code=code.replace('C->>CA: CustomerPaymentReversal','Note over C: Start of the reversal, for example, in the case of a duplicated direct debit instruction\nC->>CA: CustomerPaymentReversal')
 SPECS[n]={'kind':'sequenceDiagram','code':code,'actors':actors,'events':events,'notes':notes}
def actor(label,*roles):return (label,list(roles))
C=actor('Creditor','creditor');D=actor('Debtor','debtor');DA=actor('Debtor Agent','debtor-agent');CA=actor('Creditor Agent','creditor-agent');FA=actor('Forwarding Agent','forwarding-agent');UD=actor('Ultimate Debtor','ultimate-debtor');IP=actor('Initiating Party','initiating-party')
A={'C':actor('Creditor','creditor','ultimate-creditor'),'D':actor('Debtor (initiating party)','debtor','initiating-party','ultimate-debtor'),'DA':DA,'CA':CA}
direct=[('D','DA','CustomerCreditTransferInitiation'),('DA','D','CustomerPaymentStatusReport'),('DA','CA','FIToFICustomerCreditTransfer'),('DA','D','Notification'),('DA','D','Statement'),('CA','C','Notification'),('CA','C','Statement')]
seq(13,A,[('C','D','Invoice & Document')]+direct,['P170 says the creditor and ultimate creditor are the same actor; P172 repeats creditor rather than ultimate creditor, retained under issue-000044.'])
seq(14,{'C':C,'U':UD,'D':actor('Debtor (initiating party)','debtor','initiating-party'),'DA':DA,'CA':CA},[('U','D','Invoice')]+direct,['The picture starts with Ultimate Debtor to Debtor Invoice; it does not draw a Creditor-to-Ultimate Debtor invoice.'])
seq(15,{'C':C,'U':UD,'D':D,'I':IP,'DA':DA,'CA':CA},[('C','U','Invoice'),('U','D','Invoice'),('D','I','Invoice'),('I','DA','CustomerCreditTransferInitiation'),('DA','I','CustomerPaymentStatusReport'),('DA','CA','FIToFICustomerCreditTransfer'),('DA','D','Notification'),('DA','D','Statement'),('CA','C','Notification'),('CA','C','Statement')])
seq(16,{'C':C,'D':actor('Debtor','debtor','initiating-party','ultimate-debtor'),'F':FA,'DA':DA,'CA':CA},[('C','D','Invoice'),('D','F','CustomerCreditTransferInitiation'),('F','D','CustomerPaymentStatusReport'),('F','DA','CustomerCreditTransferInitiation'),('DA','CA','FIToFICustomerCreditTransfer'),('DA','F','CustomerPaymentStatusReport'),('F','D','CustomerPaymentStatusReport'),('DA','F','Notification'),('F','D','Notification'),('DA','F','Statement'),('F','D','Statement'),('CA','C','Notification'),('CA','C','Statement')],['Picture shares vertical levels for relayed status/notification/statement. The sequence view serializes each relay leg for readability without asserting extra timing. P191 source example: company holds overseas accounts and uses a concentrator bank.'])
seq(17,{'C':C,'U':UD,'D':actor('Debtor (initiating party)','debtor','initiating-party'),'F':FA,'DA':DA,'CA':CA},[('C','U','Invoice'),('U','D','Invoice'),('D','F','CustomerCreditTransferInitiation'),('F','D','CustomerPaymentStatusReport'),('F','DA','CustomerCreditTransferInitiation'),('DA','F','CustomerPaymentStatusReport'),('DA','CA','FIToFICustomerCreditTransfer'),('F','D','CustomerPaymentStatusReport'),('DA','F','Notification'),('F','D','Notification'),('DA','F','Statement'),('F','D','Statement'),('CA','C','Notification'),('CA','C','Statement')],['P194 source example: head office as debtor and initiating party pays for subsidiaries acting as ultimate debtors.'])
seq(18,{'C':C,'U':actor('Ultimate Debtor (initiating party)','ultimate-debtor','initiating-party'),'F':FA,'D':D,'DA':DA,'CA':CA},[('C','U','Invoice'),('U','F','CustomerCreditTransferInitiation'),('F','U','CustomerPaymentStatusReport'),('F','DA','CustomerCreditTransferInitiation'),('DA','F','CustomerPaymentStatusReport'),('F','U','CustomerPaymentStatusReport'),('DA','CA','FIToFICustomerCreditTransfer'),('DA','D','Notification'),('DA','D','Statement'),('CA','C','Notification'),('CA','C','Statement')],['P197 source example: head office initiates a payment using its foreign subsidiary account. Notifications/statements go to the depicted Debtor, distinct from initiating Ultimate Debtor.'])
DD={'C':actor('Creditor','creditor','initiating-party'),'CA':CA,'CS':actor('Clearing and Settlement Agent','clearing-and-settlement-agent'),'DA':DA,'D':D}
init=[('C','CA','CustomerDirectDebitInitiation'),('CA','C','CustomerPaymentStatusReport'),('CA','CS','FIToFICustomerDirectDebit'),('CS','CA','FIToFIPaymentStatusReport'),('CS','DA','FIToFICustomerDirectDebit'),('DA','CS','FIToFIPaymentStatusReport')]
seq(19,DD,[('C','CA','CustomerDirectDebitInitiation'),('CA','CS','FIToFICustomerDirectDebit'),('CS','DA','FIToFICustomerDirectDebit'),('DA','D','FIToFICustomerDirectDebit')],['P206/P224 describe the last leg as an optional simplified instruction/value-added service. P207 excludes the mandate and mandate management from the picture; P208–219 still define that context.'])
seq(20,DD,[init[0],init[1]],['P235/P238: creditor agent rejects initiation for non-processability, for example missing information. Unused lifelines are retained.'])
seq(21,DD,init[:4]+[('CA','C','Information')],['P240: clearing/settlement negative FIToFIPaymentStatusReport rejects the instruction before settlement. P242/P248 prefer correcting and resubmitting without involving creditor where possible. P243/P247 identify alternatives for the generic Information arrow based on booking/agreement.'])
seq(22,DD,init+[('CS','CA','FIToFIPaymentStatusReport'),('CA','C','Information')],['First two status exchanges are positive; debtor-agent status is negative, then relayed. P252–260 supply timing, repair and optional customer-information qualifications.'])
seq(23,DD,init,['P265/P269: point-to-point positive reports are optional under bilateral agreement; P271 allows partially accepted groups. P262 literally says receiver informs receiver, whereas arrows/P273/P275/P277 report to the prior sender (issue-000044).'])
seq(24,DD,init+[('D','DA','RefundRequest'),('DA','CS','PaymentReturn'),('CS','DA','FIToFIPaymentStatusReport'),('CS','CA','PaymentReturn'),('CA','CS','FIToFIPaymentStatusReport')],['P279/P283/P297: return may be initiated by debtor agent or triggered by debtor refund request; refund request is assumed non-automated and outside message scope. Source picture includes RefundRequest despite heading debtor-agent-initiated return. P294 separate settlement and P295 customer information are narrative-only.'])
seq(25,DD,init+[('C','CA','CustomerPaymentReversal'),('CA','C','CustomerPaymentStatusReport'),('CA','CS','FIToFIPaymentReversal'),('CS','CA','FIToFIPaymentStatusReport'),('CS','DA','FIToFIPaymentReversal'),('DA','CS','FIToFIPaymentStatusReport')],['P299: after settlement, a paid direct debit should not have been processed. P301 permits creditor agent originating the reversal. P313–315 separate settlement is outside picture; P317 warns return and reversal may cross.'])
FLOW={1:107,2:125,3:135,4:135,5:135,6:135,7:138,8:140,9:136,10:147,11:149,12:151,13:170,14:173,15:176,16:189,17:192,18:195,19:198,20:234,21:239,22:249,23:266,24:280,25:298}
PAGES={1:11,2:15,3:17,4:17,5:17,6:17,7:17,8:17,9:18,10:22,11:22,12:23,13:25,14:26,15:27,16:28,17:29,18:30,19:31,20:33,21:33,22:34,23:36,24:37,25:39}
for n in range(3,7):
 code=['flowchart LR\nA((" "))\nstyle A fill:#222,stroke:#222\n','flowchart LR\nA(((" ")))\n','flowchart LR\nA{" "}\n','stateDiagram-v2\nstate parallelControl <<fork>>\n'][n-3]
 SPECS[n]={'kind':'stateDiagram-v2' if n==6 else 'flowchart','code':code,'actors':{},'events':[],'notes':[['T22 row2: start of a process.'],['T22 row3: end of a process. Mermaid final-node geometry has concentric open outlines; source contains a filled central disk.'],['T22 row4: decision point with alternative paths.'],['T22 row5: more than one path may proceed in parallel. Native fork bar is shown without invented incoming/outgoing activities.']][n-3]}
for n in [1,2]:
 labels=(['Process end-to-end payment','Process customer-to-bank payment','Process interbank payment','Report','Order customer-to-bank payment','Accept customer-to-bank payment','Clear customer-to-bank payment','Settle customer-to-bank payment','Authorise customer-to-bank payment','Check customer-to-bank Payment authorisation','Validate customer-to-bank payment','Assess customer-to-bank Payment risk','Sort payment','Prepare onward interbank payment','Generate regulatory reporting information'] if n==1 else ['Process Direct Debit end-to-end','Process customer-to-bank Direct Debit','Process interbank Direct Debit','Report','Manage Direct Debit Mandate','Initiate collection of 1st/1-off Direct Debit','Initiate collection of recurrent Direct Debit','Process reject','Process return/request for refund','Process reversal','Process request for cancellation/Revocation'])
 edges=([(0,1),(0,2),(0,3),(1,4),(1,5),(1,6),(1,7),(4,8),(5,9),(5,10),(5,11),(11,14),(6,12),(6,13)] if n==1 else [(0,1),(0,2),(0,3)]+[(1,i) for i in range(5,11)])
 groups=({4:['ultimate-debtor','initiating-party','creditor','debtor'],5:['forwarding-agent','creditor-agent','debtor-agent'],6:['forwarding-agent','creditor-agent','debtor-agent'],7:['debtor','creditor','creditor-agent','debtor-agent'],14:['creditor-agent','debtor-agent']} if n==1 else {i:(['forwarding-agent','creditor','creditor-agent'] if i==9 else ['forwarding-agent','initiating-party','creditor','creditor-agent']) for i in range(5,11)})
 code='usecase-beta\ndirection TB\n'+''.join(f'N{i}("{x}")\n' for i,x in enumerate(labels))+''.join(f'N{a} --> N{b}\n' for a,b in edges);actors={}
 for group,roles in groups.items():
  for j,role in enumerate(roles):
   ident=f'A{group}_{j}';label=role.replace('-',' ').title();actors[ident]=(label,[role]);code+=f'actor {ident}("{label}")\n'
 SPECS[n]={'kind':'usecase-beta','code':code,'actors':actors,'events':[(labels[a],labels[b],'plain filled source arrow') for a,b in edges],'actor_groups':{labels[k]:v for k,v in groups.items()},'notes':['Source arrows are ordinary filled arrows; no include/extend/generalization semantics are asserted. Source has no system boundary.','Participant pictograms sit below process groups without drawn connectors. Native actors remain unconnected; the explicit placement table preserves group membership without inventing association lines.','Source colours distinguish process levels; original artwork preserves those colours and exact placement.']+(['T15 names only Debtor agent for regulatory reporting; figure also shows Creditor Agent. Source discrepancy remains issue-000044.'] if n==1 else ['Manage Direct Debit Mandate is an unconnected source use case, retained without adding a parent edge.'])}
def main(root):
 import payments_initiation_activities as activities
 SPECS.update(activities.models())
 src=next(s for s in kb.sources(root) if s['source_id']==SID);base=root/src['set_path'];inv=json.loads((root/'work/documents'/SID/'media-review-inventory.json').read_text('utf-8'));media={int(o['figure_id'][4:]):(m,o) for m in inv['media'] for o in m['occurrences']};out=base/'diagrams/initiation';mmd=root/'work/payments-initiation/mmd';results=[];fence=chr(96)*3
 for n,spec in sorted(SPECS.items()):
  page=out/f'fig-{n:04d}.md';item,occ=media[n];flow=next((base/'flows').glob(f'flow-{SID}-p{FLOW[n]}-*.md'));fm,_=kb.metadata(flow);code=spec['code'];pids=sorted({'participant-'+SID+'-'+slug for _,roles in spec['actors'].values() for slug in roles});issues=['issue-000044'] if n in [1,13,23] else []
  notes=spec['notes']+['Actor pictograms identify roles in this context, not a fixed institutional identity. Source narrative may describe participants/steps omitted from this bounded figure.','Part1 message labels alone do not establish exact supplied schema versions. Original figures and their complete rendered page remain the evidence for geometry and line styling.']
  title=' / '.join(occ['heading_path'][1:])+' — figure '+str(n)
  meta={'template':False,'document_kind':'diagram','review_status':'needs-review','manual_curated':True,'diagram_id':f'fig-{n:04d}','title':title,'domain':'payments','source_ids':[SID],'source_editions':[src['source_edition']],'message_sets':['payments-initiation'],'participant_ids':pids,'flow_ids':[fm['flow_id']],'content_origin':'source-reconstruction','diagram_kind':spec['kind'],'original_asset':item['original'],'source_locations':[{'source_id':SID,'locator':occ['source_locator'],'heading_path':occ['heading_path'],'xml_path':occ['xml_path'],'rendered_file_page':PAGES[n]}],'render_status':'not-run','visual_review':'not-run','limitations':notes,'issue_ids':issues,'updated':DATE}
  body='# '+title+'\n\n'+kb.source_link(root,page,src)+'; '+occ['source_locator']+'; Word file/printed page '+str(PAGES[n])+'.\n\n'+kb.link(page,root/item['original'],'Original figure')+' · '+kb.link(page,root/f'domains/payments/assets/{SID}/word-render/page-{PAGES[n]}.png','Complete Word-rendered page')+' · '+kb.link(page,flow,'Reusable flow')+'\n\n## Source reconstruction\n\n'+fence+'mermaid\n'+code+fence+'\n\n## Participants and roles\n\n'+kb.table(['Occurrence','Literal label','Scoped roles'],[[i,label,'; '.join(kb.link(page,root/'shared/reference/participants'/('participant-'+SID+'-'+slug+'.md'),slug) for slug in roles)] for i,(label,roles) in spec['actors'].items()])
  if spec.get('actor_groups'):body+='\n## Source icon placement\n\n'+kb.table(['Process group','Pictograms beneath group (no source connectors)'],[[x,', '.join(y)] for x,y in spec['actor_groups'].items()])
  body+='\n## Relationships and activities\n\n'+kb.table(['Order','From','To','Literal label / direction'],[[i+1,a,b,l] for i,(a,b,l) in enumerate(spec['events'])])+'\n## Source qualifications\n\n'+'\n'.join('- '+s for s in notes)+'\n\n## Rendering and visual review\n\nPending actual parse/render and comparison.\n'
  extract_workbooks.write(root,page,kb.front(meta)+body,'job-000001');extract_workbooks.write(root,mmd/f'fig-{n:04d}.mmd',code,'job-000001')
  results.append({'figure_id':f'fig-{n:04d}','path':page.relative_to(root).as_posix(),'original':item['original'],'original_sha256':item['original_sha256'],'mermaid':(mmd/f'fig-{n:04d}.mmd').relative_to(root).as_posix(),'mermaid_sha256':hashlib.sha256(code.encode()).hexdigest(),'source_locator':occ['source_locator'],'word_file_page':PAGES[n],'flow':flow.relative_to(root).as_posix(),'flow_start':FLOW[n],'actors':spec['actors'],'events':spec['events'],'limitations':notes,'issue_ids':issues,'visual_review':{'status':'not-run'}})
 kb.dump(root/'work/payments-initiation/models.json',{'source_id':SID,'source_sha256':src['sha256'],'models':results});print(json.dumps({'diagrams':len(results),'relationships':sum(len(x['events']) for x in results)}))
if __name__=='__main__':
 a=argparse.ArgumentParser();a.add_argument('--root',type=Path,default=Path(__file__).resolve().parents[1]);main(a.parse_args().root)
